#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONVERSION_REG 0x00

void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    int i2c_fd;
    uint8_t buffer[3];
    double voltage;

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, close_i2c);

    while (1) {
        // Start single conversion
        buffer[0] = CONVERSION_REG | 0b10000000; // Single-shot mode, channel A0
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            break;
        }

        // Wait for conversion to complete (approx 66 ms)
        usleep(70000);

        // Read the result
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from I2C device");
            break;
        }

        // Convert the 16-bit result to voltage
        int16_t raw_value = (buffer[1] << 8) | buffer[2];
        voltage = (raw_value * 4.096) / 32767.0;

        printf("ADC Reading: %.4f V\n", voltage);
        fflush(stdout);

        // Sleep for 0.5 seconds
        sleep(1);
    }

    close_i2c(i2c_fd);
    return EXIT_SUCCESS;
}

