#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEVICE "/dev/i2c-1"
#define ADDRESS 0x5A

int main() {
    int file;
    char *filename = DEVICE;
    uint8_t buffer[3];

    // Open the I2C bus
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(file, I2C_SLAVE, ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read temperature data from MLX90614
        if (read(file, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from the sensor");
            close(file);
            return EXIT_FAILURE;
        }

        // Convert raw data to Celsius
        float ambient_temp = (buffer[0] << 8 | buffer[1]) / 16.0;
        float object_temp = (buffer[2] << 8 | buffer[3]) / 16.0;

        printf("Ambient Temperature: %.2f°C\n", ambient_temp);
        printf("Object Temperature: %.2f°C\n", object_temp);

        sleep(5);
    }

    // Close the I2C bus
    close(file);
    return EXIT_SUCCESS;
}

