    gpiod_chip_close(chip);
    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x28
#define CONVERSION_TIME_US 86000

// Function to initialize I2C bus
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to read 16-bit value from ADS1115
uint16_t ads1115_read(int fd) {
    uint8_t buffer[3];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from ADS1115");
        return UINT16_MAX;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to convert raw ADC value to voltage
float adc_to_voltage(uint16_t adc_value) {
    // Assuming VREF = 4.096V and 16-bit resolution
    return (adc_value * 4.096) / 65535.0;
}

int main() {
    int i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        printf("\nInterrupted by user\n");
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint16_t adc_value = ads1115_read(i2c_fd);
        if (adc_value == UINT16_MAX) {
            fprintf(stderr, "Invalid ADC reading\n");
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        printf("ADC Value: %u, Voltage: %.4fV\n", adc_value, voltage);

        usleep(CONVERSION_TIME_US);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

