#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONVERSION_REG 0x00

int i2c_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_error(const char *message) {
    perror(message);
    cleanup();
    exit(EXIT_FAILURE);
}

uint16_t read_adc_conversion() {
    uint8_t buffer[3];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        handle_error("Failed to read from I2C device");
    }

    // Combine the two bytes into a 16-bit value
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        handle_error("Failed to set up signal handler");
    }

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        handle_error("Failed to open I2C device");
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        handle_error("Failed to set I2C slave address");
    }

    // Read the conversion register
    uint16_t adc_value = read_adc_conversion();

    printf("ADC Conversion Value: %d\n", adc_value);

    cleanup();
    return EXIT_SUCCESS;
}

