    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_LINES[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "output_test", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output for line %d\n", GPIO_LINES[i]);
            goto cleanup;
        }
