#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEVICE "/dev/i2c-1"
#define SI7021_ADDRESS 0x40

int i2c_fd;

void cleanup() {
    close(i2c_fd);
}

void read_temperature_and_humidity() {
    uint8_t command[2];
    uint8_t data[3];

    // Send temperature command
    command[0] = 0xF3;
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to write temperature command");
        return;
    }

    // Wait for conversion to complete (around 60ms)
    usleep(70 * 1000);

    // Read temperature data
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read temperature data");
        return;
    }

    // Calculate temperature in Celsius
    float temp_c = ((data[0] << 8) | data[1]) * 175.72 / 65536 - 46.85;

    // Send humidity command
    command[0] = 0xF5;
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to write humidity command");
        return;
    }

    // Wait for conversion to complete (around 25ms)
    usleep(30 * 1000);

    // Read humidity data
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read humidity data");
        return;
    }

    // Calculate humidity in percent
    float humidity = ((data[0] << 8) | data[1]) * 125.0 / 65536 - 6;

    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp_c, humidity);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        read_temperature_and_humidity();
        sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONVERSION_TIME_US 860

int i2c_fd;

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void die(const char *msg) {
    perror(msg);
    close_i2c();
    exit(EXIT_FAILURE);
}

uint16_t read_adc_channel(uint8_t channel) {
    uint8_t buf[3];
    uint16_t adc_value;

    // Start single conversion
    buf[0] = 0b11010000 | (channel & 0x03);
    if (write(i2c_fd, buf, 1) != 1) {
        die("Failed to write to ADS1115");
    }

    // Wait for conversion to complete
    usleep(CONVERSION_TIME_US);

    // Read two bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        die("Failed to read from ADS1115");
    }

    // Combine the two bytes into a 16-bit value
    adc_value = ((uint16_t)buf[0] << 8) | buf[1];

    return adc_value;
}

int main() {
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data msgset[1];
    uint8_t addr = ADS1115_ADDRESS;

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        die("Failed to open I2C device");
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        die("Failed to set I2C slave address");
    }

    for (int i = 0; i < 3; ++i) {
        uint16_t adc_value = read_adc_channel(0); // Assuming we're reading from channel 0
        printf("ADC Reading %d: 0x%04X\n", i + 1, adc_value);
        sleep(1);
    }

    close_i2c();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define CYCLES 256

static struct gpiod_chip *chip;
static struct gpiod_line *lines[6];
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i, j;
    const char *chip_name = "gpiochip0";
    const char *line_names[] = {"8", "9", "10", "11", "23", "24"};
    unsigned int states[] = {0, 1};

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < 6; i++) {
        lines[i] = gpiod_chip_get_line(chip, atoi(line_names[i]));
        if (!lines[i]) {
            perror("Failed to get line");
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "output_control", states[i])) {
            perror("Failed to request line as output");
            goto cleanup;
        }
    }

    // Main loop
    for (j = 0; j < CYCLES && running; j++) {
        for (i = 0; i < 6; i++) {
            if (gpiod_line_set_value(lines[i], states[j % 2])) {
                perror("Failed to set line value");
                goto cleanup;
            }
            printf("GPIO %s: %d\n", line_names[i], states[j % 2]);
        }
        usleep(100000); // 100ms delay
    }

cleanup:
    // Release lines
    for (i = 0; i < 6; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

