}

int main() {
    int ret;
    unsigned int value;

    // Register signal handler for graceful exit
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    ret = gpiod_line_request_output(line, "output_example", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Set GPIO line high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO line high");
            continue;
        }
        printf("GPIO %d set to HIGH\n", GPIO_LINE);

        // Read GPIO line state
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            perror("Failed to read GPIO line state");
            continue;
        }
        if (value != 1) {
            fprintf(stderr, "Invalid GPIO state: expected 1, got %u\n", value);
            continue;
        }
        printf("Read GPIO %d state: HIGH\n", GPIO_LINE);

        // Wait for 1 second
        sleep(1);

        // Set GPIO line low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO line low");
            continue;
        }
        printf("GPIO %d set to LOW\n", GPIO_LINE);

        // Read GPIO line state
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            perror("Failed to read GPIO line state");
            continue;
        }
        if (value != 0) {
            fprintf(stderr, "Invalid GPIO state: expected 0, got %u\n", value);
            continue;
        }
        printf("Read GPIO %d state: LOW\n", GPIO_LINE);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up on normal exit
    cleanup(0);

    return EXIT_SUCCESS;
}

