#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIG_PIN "gpiochip0:line17"
#define ECHO_PIN "gpiochip0:line18"

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;

void cleanup(int signum) {
    if (trig_line) {
        gpiod_line_release(trig_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting...\n");
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, 17);
    if (!trig_line) {
        perror("Failed to get trigger line");
        goto out_close_chip;
    }

    echo_line = gpiod_chip_get_line(chip, 18);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto out_release_trig_line;
    }

    if (gpiod_line_request_output(trig_line, "trigger", 0)) {
        perror("Failed to request trigger line as output");
        goto out_release_echo_line;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line as input");
        goto out_release_trig_line;
    }

    while (1) {
        // Trigger pulse
        if (gpiod_line_set_value(trig_line, 1)) {
            perror("Failed to set trigger line high");
            goto out_release_lines;
        }
        usleep(10); // 10 microseconds pulse
        if (gpiod_line_set_value(trig_line, 0)) {
            perror("Failed to set trigger line low");
            goto out_release_lines;
        }

        // Wait for echo line to go high
        int ret = gpiod_line_event_wait(echo_line, 500000); // 500ms timeout
        if (ret < 0) {
            perror("Failed to wait for echo line event");
            goto out_release_lines;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(echo_line, &event)) {
            perror("Failed to read echo line event");
            goto out_release_lines;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            fprintf(stderr, "Unexpected event type\n");
            continue;
        }

        uint64_t start_time = event.timestamp.tv_sec * 1e9 + event.timestamp.tv_nsec;

        // Wait for echo line to go low
        ret = gpiod_line_event_wait(echo_line, 500000); // 500ms timeout
        if (ret < 0) {
            perror("Failed to wait for echo line event");
            goto out_release_lines;
        }

        if (gpiod_line_event_read(echo_line, &event)) {
            perror("Failed to read echo line event");
            goto out_release_lines;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            fprintf(stderr, "Unexpected event type\n");
            continue;
        }

        uint64_t end_time = event.timestamp.tv_sec * 1e9 + event.timestamp.tv_nsec;

        double duration = (end_time - start_time) / 2.0 / 1e6; // Convert to cm

        if (duration >= 0 && duration <= 400) { // Valid distance range
            printf("Distance: %.2f cm\n", duration);
        } else {
            fprintf(stderr, "Invalid distance reading\n");
        }

        sleep(1);
    }

out_release_lines:
    gpiod_line_release(trig_line);
out_release_echo_line:
    gpiod_line_release(echo_line);
out_close_chip:
    gpiod_chip_close(chip);
    return 1;
}

