#define CYCLES 3
#define DELAY_SECONDS 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        perror("Failed to get line 2");
        goto cleanup_chip;
    }

    ret = gpiod_line_request_output(line, CONSUMER, GPIOD_LINE_INITIAL_VALUE_LOW);
    if (ret < 0) {
        perror("Failed to request line 2 as output");
        goto cleanup_line;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get line 3");
        goto cleanup_line_2;
    }

    ret = gpiod_line_request_output(line, CONSUMER, GPIOD_LINE_INITIAL_VALUE_LOW);
    if (ret < 0) {
        perror("Failed to request line 3 as output");
        goto cleanup_line_3;
    }

    for (int i = 0; i < CYCLES; ++i) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            perror("Failed to set value of line 2");
            goto cleanup_lines;
        }
        printf("GPIO 2: %s\n", gpiod_line_get_value(line) ? "HIGH" : "LOW");

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            perror("Failed to set value of line 3");
            goto cleanup_lines;
        }
        printf("GPIO 3: %s\n", gpiod_line_get_value(line) ? "HIGH" : "LOW");

        sleep(DELAY_SECONDS);
    }

cleanup_lines:
    gpiod_line_release(line);
cleanup_line_3:
    gpiod_line_release(line);
cleanup_line_2:
    gpiod_line_release(line);
cleanup_line:
    gpiod_chip_close(chip);
cleanup_chip:
    return EXIT_SUCCESS;
}

