#include <pigpio.h>

#define PWM_GPIO_1 2
#define PWM_GPIO_2 3
#define PWM_GPIO_3 18

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_GPIO_1, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_2, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_GPIO_1, 1000); // 1 kHz
    gpioSetPWMrange(PWM_GPIO_1, 256);

    gpioSetPWMfrequency(PWM_GPIO_2, 1000); // 1 kHz
    gpioSetPWMrange(PWM_GPIO_2, 256);

    gpioSetPWMfrequency(PWM_GPIO_3, 1000); // 1 kHz
    gpioSetPWMrange(PWM_GPIO_3, 256);

    signal(SIGINT, signal_handler);

    while (!stop) {
        gpioSetPWMdutycycle(PWM_GPIO_1, 128); // 50%
        gpioSetPWMdutycycle(PWM_GPIO_2, 192); // 75%
        gpioSetPWMdutycycle(PWM_GPIO_3, 64);  // 25%

        printf("GPIO 2: 50%%, GPIO 3: 75%%, GPIO 18: 25%%\n");

        sleep(150); // 0.15 seconds
    }

    gpioSetPWMdutycycle(PWM_GPIO_1, 0);
    gpioSetPWMdutycycle(PWM_GPIO_2, 0);
    gpioSetPWMdutycycle(PWM_GPIO_3, 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}

