#define I2C_DEVICE "/dev/i2c-1"
#define OPT3001_ADDRESS 0x44

int main() {
    int file;
    char *filename = I2C_DEVICE;
    uint8_t buffer[2];

    // Open the I2C device
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(file, I2C_SLAVE, OPT3001_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    // Read two bytes from the OPT3001
    if (read(file, buffer, 2) != 2) {
        perror("Failed to read from the sensor");
        close(file);
        return EXIT_FAILURE;
    }

    // Close the I2C device
    close(file);

    // Convert the two bytes to a 16-bit integer
    uint16_t result = (buffer[0] << 8) | buffer[1];
    printf("OPT3001 Measurement: 0x%04X\n", result);

    return EXIT_SUCCESS;
}

