    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_LINES[i]);
            goto cleanup;
