    ssize_t bytes_read;
    char buffer[64];
    double temperature;

    fd = open(device_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open device file");
        return -1;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read <= 0) {
        fprintf(stderr, "Failed to read from device\n");
        return -1;
    }
    buffer[bytes_read] = '\0';

    // Find the temperature value in the buffer
    const char *temp_str = strstr(buffer, "t=");
    if (!temp_str) {
        fprintf(stderr, "Invalid data format\n");
        return -1;
    }

    temp_str += 2; // Skip "t="
    temperature = atof(temp_str) / 1000.0;

    printf("Temperature: %.3f°C\n", temperature);
    return 0;
}

