#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDRESS 0x40

// Function prototypes
int i2c_open(const char *device);
void i2c_close(int fd);
int htu21d_read_temperature(int fd);

int main() {
    int i2c_fd;
    float temperature;

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read temperature from HTU21D
        temperature = htu21d_read_temperature(i2c_fd);
        if (temperature == -1) {
            fprintf(stderr, "Failed to read valid temperature from HTU21D\n");
            i2c_close(i2c_fd);
            return EXIT_FAILURE;
        }
        printf("Temperature: %.2f°C\n", temperature);

        // Wait for 60 seconds
        sleep(60);
    }

    // Close I2C device
    i2c_close(i2c_fd);
    return EXIT_SUCCESS;
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

int htu21d_read_temperature(int fd) {
    uint8_t cmd[3] = {0xF3}; // Command to measure temperature
    uint8_t buffer[3];

    // Send command to start measurement
    if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send measurement command to HTU21D");
        return -1;
    }

    // Wait for conversion to complete (at least 50ms)
    usleep(50000);

    // Read 3 bytes of data
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read data from HTU21D");
        return -1;
    }

    // Calculate temperature in Celsius
    uint16_t raw_temp = ((uint16_t)buffer[0] << 8) | buffer[1];
    float temperature = -46.85 + 175.72 * (raw_temp / 65536.0);

    // Check for invalid temperature value
    if (isnan(temperature) || isinf(temperature)) {
        return -1;
    }

    return temperature;
}

