#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO_17 17
#define PWM_GPIO_22 22
#define PWM_GPIO_27 27
#define PWM_FREQ 1000
#define PWM_RANGE 255

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int rc;

    // Initialize pigpio library
    if ((rc = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    // Set up GPIO pins as PWM outputs
    gpioSetMode(PWM_GPIO_17, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_22, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_27, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO_17, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO_17, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO_22, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO_22, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO_27, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO_27, PWM_RANGE);

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    while (!stop) {
        // Apply PWM duty cycle of 50%
        gpioSetPWMdutycycle(PWM_GPIO_17, PWM_RANGE / 2);
        gpioSetPWMdutycycle(PWM_GPIO_22, PWM_RANGE / 2);
        gpioSetPWMdutycycle(PWM_GPIO_27, PWM_RANGE / 2);

        printf("GPIO 17: 50%%\n");
        printf("GPIO 22: 50%%\n");
        printf("GPIO 27: 50%%\n");

        sleep(1);
    }

    // Clean up GPIO settings
    gpioSetPWMdutycycle(PWM_GPIO_17, 0);
    gpioSetPWMdutycycle(PWM_GPIO_22, 0);
    gpioSetPWMdutycycle(PWM_GPIO_27, 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}

