int main() {
    int i2c_fd;
    uint8_t buffer[2];

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read the red channel value
        buffer[0] = 0xD0; // Command register for clear channel low byte
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write command to TCS34725");
            break;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read data from TCS34725");
            break;
        }
        uint16_t clear_channel = (buffer[1] << 8) | buffer[0];
        printf("Clear Channel: %u\n", clear_channel);

        // Sleep for 0.2 seconds
        usleep(200 * 1000);
    }

    // Close the I2C device
    close_i2c(i2c_fd);

    return EXIT_SUCCESS;
}

