#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SSD1306_ADDRESS 0x3C

void i2c_write_byte(int file, uint8_t address, uint8_t data) {
    if (write(file, &data, 1) != 1) {
        perror("Failed to write byte");
        exit(EXIT_FAILURE);
    }
}

void ssd1306_init(int file) {
    // Initialize SSD1306 commands
    uint8_t init_commands[] = {
        0xAE, 0xD5, 0xF0, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14,
        0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xDB, 0x40,
        0xA4, 0xA6, 0xAF
    };

    for (size_t i = 0; i < sizeof(init_commands); ++i) {
        i2c_write_byte(file, SSD1306_ADDRESS, init_commands[i]);
    }
}

void ssd1306_display_text(int file, const char *text) {
    uint8_t buffer[128];
    memset(buffer, 0, sizeof(buffer));

    size_t len = strlen(text);
    if (len > 128) {
        len = 128;
    }

    for (size_t i = 0; i < len; ++i) {
        buffer[i] = text[i];
    }

    i2c_write_byte(file, SSD1306_ADDRESS, 0xB0); // Set page start address
    i2c_write_byte(file, SSD1306_ADDRESS, 0x00); // Set column start address
    i2c_write_byte(file, SSD1306_ADDRESS, 0x10);

    for (size_t i = 0; i < len; ++i) {
        i2c_write_byte(file, SSD1306_ADDRESS, buffer[i]);
    }
}

int main() {
    int file;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open I2C device
    if ((file = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Request GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(file);
        return EXIT_FAILURE;
    }

    // Request GPIO line for interrupt handling
    line = gpiod_chip_get_line(chip, 17); // Example GPIO pin number
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "interrupt")) {
        perror("Failed to request input on GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(file);
        return EXIT_FAILURE;
    }

    // Initialize SSD1306
    ssd1306_init(file);

    // Main loop
    while (1) {
        for (int i = 0; i <= 9; ++i) {
            char buffer[2];
            snprintf(buffer, sizeof(buffer), "%d", i);
            ssd1306_display_text(file, buffer);
            usleep(100000); // 0.1 seconds
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(file);

    return EXIT_SUCCESS;
}

