    lines = malloc(sizeof(struct gpiod_line *) * sizeof(GPIO_LINES));
    if (!lines) {
        perror("Failed to allocate memory for GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < sizeof(GPIO_LINES)/sizeof(GPIO_LINES[0]); i++) {
