#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FPS 30

void capture_image(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == ioctl(fd, VIDIOC_QUERYBUF, &buf)) {
        perror("VIDIOC_QUERYBUF");
        return;
    }

    void *addr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == addr) {
        perror("mmap");
        return;
    }

    if (-1 == ioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        munmap(addr, buf.length);
        return;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == ioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        munmap(addr, buf.length);
        return;
    }

    if (-1 == ioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        munmap(addr, buf.length);
        return;
    }

    FILE *file = fopen("captured_image.jpg", "wb");
    if (!file) {
        perror("fopen");
        munmap(addr, buf.length);
        return;
    }

    fwrite(addr, 1, buf.bytesused, file);
    fclose(file);

    if (-1 == ioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
    }

    if (-1 == ioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    munmap(addr, buf.length);
}

int main() {
    int fd = open(DEVICE, O_RDWR);
    if (-1 == fd) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (-1 == ioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == ioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == ioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_IGN);
    while (1) {
        capture_image(fd);
        usleep((1000 / FPS) * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

