void i2c_write_byte(int file, unsigned char data) {
    if (write(file, &data, 1) != 1) {
        perror("Failed to write byte");
        exit(EXIT_FAILURE);
    }
}

void lcd_command(int file, unsigned char cmd) {
    i2c_write_byte(file, cmd | 0x00);
    usleep(500);
}

void lcd_data(int file, unsigned char data) {
    i2c_write_byte(file, data | 0x40);
    usleep(500);
}

void lcd_init(int file) {
    lcd_command(file, 0x33); // Initialize
    lcd_command(file, 0x32); // Set interface length
    lcd_command(file, 0x06); // Entry mode set
    lcd_command(file, 0x0C); // Display on/off control
    lcd_command(file, 0x28); // Function set
    lcd_command(file, 0x01); // Clear display
    usleep(2000);
}

void lcd_print_string(int file, const char *str) {
    while (*str) {
        lcd_data(file, *str++);
    }
}

