    if ((file = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, LCD_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    lcd_init(file);

    signal(SIGINT, [](int signum) {
        printf("\nInterrupted by user\n");
        close(file);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        lcd_command(file, 0x80); // Move cursor to first line
        lcd_print_string(file, "Hello, World!");
        lcd_command(file, 0xC0); // Move cursor to second line
