#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 255

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int rc;
    uint32_t gpio_state;

    // Initialize pigpio library
    if ((rc = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    // Set up GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set up PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    while (!stop) {
        // Toggle PWM duty cycle between 0 and 255
        for (uint32_t i = 0; i <= PWM_RANGE; i++) {
            gpioSetPWMdutycycle(GPIO_PIN, i);
            gpioState = gpioRead(GPIO_PIN);
            printf("GPIO %d set to %u\n", GPIO_PIN, gpioState);
            sleep(1);
        }
        for (uint32_t i = PWM_RANGE; i > 0; i--) {
            gpioSetPWMdutycycle(GPIO_PIN, i);
            gpioState = gpioRead(GPIO_PIN);
            printf("GPIO %d set to %u\n", GPIO_PIN, gpioState);
            sleep(1);
        }
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

