        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, 23);
    if (!trig_line) {
        perror("Failed to get trigger line");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, 24);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto error;
    }

    if (gpiod_line_request_output(trig_line, "trigger", 0)) {
        perror("Failed to request trigger line as output");
        goto error;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line as input");
        goto error;
    }

    while (1) {
        // Send a 10us pulse to the trigger pin
        if (gpiod_line_set_value(trig_line, 1)) {
            perror("Failed to set trigger line high");
            goto error;
        }
        usleep(10);
        if (gpiod_line_set_value(trig_line, 0)) {
            perror("Failed to set trigger line low");
            goto error;
        }

        // Wait for the echo pin to go high
        int ret = gpiod_line_event_wait(echo_line, 500000); // 0.5s timeout
        if (ret == -1) {
            perror("Failed to wait for echo event");
            goto error;
        } else if (ret == 0) {
            fprintf(stderr, "No echo response received\n");
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(echo_line, &event)) {
            perror("Failed to read echo event");
            goto error;
        }

        // Wait for the echo pin to go low
        ret = gpiod_line_event_wait(echo_line, 500000); // 0.5s timeout
        if (ret == -1) {
            perror("Failed to wait for echo event");
            goto error;
        } else if (ret == 0) {
            fprintf(stderr, "No echo response received\n");
            continue;
        }

        if (gpiod_line_event_read(echo_line, &event)) {
            perror("Failed to read echo event");
            goto error;
        }

        uint64_t start_time = event.timestamp.tv_sec * 1e9 + event.timestamp.tv_nsec;
        uint64_t end_time = gpiod_line_event_read_timestamp(echo_line).tv_sec * 1e9 + gpiod_line_event_read_timestamp(echo_line).tv_nsec;

