#define ADS1115_ADDRESS 0x48
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/ads1115"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    FILE *i2c_fd;
    uint16_t adc_value;
    char buffer[10];
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = fopen(I2C_DEVICE, "r+");
    if (!i2c_fd) {
        perror("Failed to open I2C device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up MQTT client
    MQTTClient_create(&client, MQTT_BROKER, "ads1115_publisher", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    ret = MQTTClient_connect(client, &conn_opts);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        fclose(i2c_fd);
        gpiod_chip_close(chip);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    for (int i = 0; i < 10 && running; i++) {
        // Read ADC value from ADS1115
        fseek(i2c_fd, 0, SEEK_SET);
        fwrite("\x48\x10\x00\x00", 1, 4, i2c_fd);
        fflush(i2c_fd);
        usleep(1000);
        fread(buffer, 1, 2, i2c_fd);
        adc_value = ((buffer[0] << 8) | buffer[1]) >> 4;

