        MQTTClient_publishMessage(client, MQTT_TOPIC, &MQTTClient_message_initializer);
        MQTTClient_message pubmsg = {buffer, strlen(buffer), 0, 1};
        ret = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
        if (ret != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
        }
    }

    // Clean up
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    fclose(i2c_fd);
    gpiod_chip_close(chip);

