        perror("Failed to request buffers");
        return EXIT_FAILURE;
    }

    // Map the buffer
    buffer = mmap(NULL, CAPTURE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        return EXIT_FAILURE;
    }

    // Queue the buffer
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Failed to queue buffer");
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Failed to stop streaming");
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    // Save the image to a file
    FILE *file = fopen("captured_image.rgb", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, 1, CAPTURE_SIZE, file) != CAPTURE_SIZE) {
        perror("Failed to write to file");
        fclose(file);
        munmap(buffer, CAPTURE_SIZE);
        return EXIT_FAILURE;
    }

    fclose(file);
    munmap(buffer, CAPTURE_SIZE);

    printf("Image captured and saved as 'captured_image.rgb'\n");

    return EXIT_SUCCESS;
}

