#include <termios.h>

void set_interface_attribs(int fd, int speed) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    cfsetospeed(&tty, (speed_t)speed);
    cfsetispeed(&tty, (speed_t)speed);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;         /* 8-bit characters */
    tty.c_cflag &= ~PARENB;     /* no parity bit */
    tty.c_cflag &= ~CSTOPB;     /* only need 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;    /* no hardware flowcontrol */

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); /* raw input */

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); /* no software flowcontrol */

    tty.c_oflag = 0;       /* no remapping, no delays */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

void set_mincount(int fd, int mcount) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    tty.c_cc[VMIN] = mcount ? 1 : 0;
    tty.c_cc[VTIME] = 5;        /* half second timer */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    const char *portname = "/dev/ttyS0";
    int fd;

    // Open the serial port
    fd = open(portname, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Unable to open serial port");
        return EXIT_FAILURE;
    }

    // Set up the serial port
    set_interface_attribs(fd, B9600);
    set_mincount(fd, 0);                /* set to pure timed read */

    printf("Serial port %s opened and configured.\n", portname);

    // Read from the serial port
    unsigned char buffer[256];
    ssize_t num_bytes_read;
    while ((num_bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        write(STDOUT_FILENO, buffer, num_bytes_read);
    }

    if (num_bytes_read == -1 && errno != EAGAIN) {
        perror("Error reading from serial port");
    }

    // Close the serial port
    close(fd);

    printf("Serial port closed.\n");

    return EXIT_SUCCESS;
}

