    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request trig line
    trig = gpiod_chip_get_line(chip, 17);
    if (!trig) {
        perror("Failed to get trig line");
        goto err_close_chip;
