    // Configure trig line as output
    ret = gpiod_line_request_output(trig, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to configure trig line as output");
        goto err_release_trig;
    }

    // Request echo line
    echo = gpiod_chip_get_line(chip, 18);
    if (!echo) {
        perror("Failed to get echo line");
        goto err_release_trig;
    }

    // Configure echo line as input
    ret = gpiod_line_request_input(echo, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to configure echo line as input");
        goto err_release_echo;
    }

    // Trigger pulse
    ret = gpiod_line_set_value(trig, 1);
    if (ret < 0) {
        perror("Failed to set trig line high");
        goto err_release_echo;
    }
    usleep(10); // 10 microseconds pulse width
    ret = gpiod_line_set_value(trig, 0);
    if (ret < 0) {
        perror("Failed to set trig line low");
        goto err_release_echo;
    }

    // Wait for echo pulse
    unsigned int start_time = time(NULL);
    while (time(NULL) - start_time < 2) { // Give up after 2 seconds
        if (gpiod_line_get_value(echo)) {
            break;
        }
        usleep(1000); // Check every millisecond
    }

    if (!gpiod_line_get_value(echo)) {
        fprintf(stderr, "No echo response received\n");
        ret = EXIT_FAILURE;
        goto err_release_echo;
    }

    // Measure duration of echo pulse
    start_time = time(NULL);
    while (time(NULL) - start_time < 2) { // Give up after 2 seconds
        if (!gpiod_line_get_value(echo)) {
            break;
        }
        usleep(1000); // Check every millisecond
    }

    unsigned long duration = (time(NULL) - start_time) * 1000 + (gettimeofday(NULL)->tv_usec / 1000);

    // Calculate distance
    double distance = (duration * 0.343) / 2; // Speed of sound in air at room temperature

    printf("Distance: %.2f cm\n", distance);

err_release_echo:
    gpiod_line_release(echo);
err_release_trig:
    gpiod_line_release(trig);
