void read_mpu6050(int file) {
    unsigned char buffer[6];
    if (read(file, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from MPU6050");
        return;
    }

    int16_t accel_x = (buffer[0] << 8) | buffer[1];
    int16_t accel_y = (buffer[2] << 8) | buffer[3];
    int16_t accel_z = (buffer[4] << 8) | buffer[5];

    printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
}

int main() {
    int file;
    if ((file = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        printf("\nInterrupted by user.\n");
        exit(EXIT_SUCCESS);
    });

    while (1) {
        read_mpu6050(file);
        usleep(100 * 1000); // Sleep for 0.1 seconds
    }

    close(file);
    return EXIT_SUCCESS;
}

