#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {2, 3, 17}
#define CYCLES 3
#define DELAY 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int i, ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "output", 0);
        if (ret < 0) {
            perror("Failed to request output");
            goto cleanup;
        }
    }

    // Main loop
    for (i = 0; i < CYCLES && running; i++) {
        for (int j = 0; j < 3; j++) {
            ret = gpiod_line_set_value(lines[j], !gpiod_line_get_value(lines[j]));
            if (ret < 0) {
                perror("Failed to set line value");
                goto cleanup;
            }

            printf("GPIO %d: %s\n", GPIO_LINES[j], gpiod_line_get_value(lines[j]) ? "HIGH" : "LOW");
        }
        sleep(DELAY);
    }

cleanup:
    // Release lines
    for (i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

