#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_I2C_ADDRESS 0x44
#define SHT31_MEAS_HIGHREP_STRETCH_CMD "\xF3\x2D"
#define SHT31_STATUS_REG_CMD "\xF3\xE0"

int i2c_fd;

void open_i2c_device() {
    const char *i2c_dev = "/dev/i2c-1";
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_temperature_and_humidity(float *temperature, float *humidity) {
    uint8_t cmd[2] = SHT31_MEAS_HIGHREP_STRETCH_CMD;
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send measurement command");
        return;
    }

    usleep(500000); // Wait for measurement to complete

    uint8_t data[6];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read measurement data");
        return;
    }

    uint16_t status_reg;
    cmd[0] = SHT31_STATUS_REG_CMD[0];
    cmd[1] = SHT31_STATUS_REG_CMD[1];
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send status register command");
        return;
    }

    if (read(i2c_fd, &status_reg, sizeof(status_reg)) != sizeof(status_reg)) {
        perror("Failed to read status register");
        return;
    }

    if ((status_reg >> 13) & 0x01) { // Check for CRC error
        fprintf(stderr, "CRC error in measurement\n");
        return;
    }

    *temperature = -45 + 175 * (data[0] * 256 + data[1]) / 65535.0;
    *humidity = 100 * (data[3] * 256 + data[4]) / 65535.0;
}

void cleanup() {
    close(i2c_fd);
}

int main() {
    signal(SIGINT, (void (*)(int))cleanup);

    open_i2c_device();

    while (1) {
        float temperature, humidity;
        read_temperature_and_humidity(&temperature, &humidity);

        if (!isnan(temperature) && !isnan(humidity)) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Invalid measurement\n");
        }

        sleep(5);
    }

    return 0;
}

