        if (gpiod_line_set_value(lines[i], 0)) {
            perror("Failed to set GPIO line value");
            goto err_release_lines;
        }
    }

    // Simulate running once and then clean up
    sleep(1);

err_release_lines:
    for (int i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
err_free_lines:
    free(lines);
    gpiod_chip_close(chip);
