#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PINS {17, 18, 22, 27}

int main() {
    int ret;
    unsigned gpio_pins[] = GPIO_PINS;
    size_t num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

    // Initialize pigpio library
    if ((ret = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error_text(ret));
        return EXIT_FAILURE;
    }

    // Set up GPIO pins as output with initial value low
    for (size_t i = 0; i < num_pins; ++i) {
        if ((ret = gpioSetMode(gpio_pins[i], PI_OUTPUT)) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", gpio_pins[i], pigpio_error_text(ret));
            goto cleanup;
        }
        if ((ret = gpioWrite(gpio_pins[i], 0)) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d: %s\n", gpio_pins[i], pigpio_error_text(ret));
            goto cleanup;
        }
    }

    // Apply PWM to each pin at 50% duty cycle
    for (size_t i = 0; i < num_pins; ++i) {
        if ((ret = gpioSetPWMfrequency(gpio_pins[i], 1000)) < 0) {
            fprintf(stderr, "Failed to set frequency for GPIO %d: %s\n", gpio_pins[i], pigpio_error_text(ret));
            goto cleanup;
        }
        if ((ret = gpioSetPWMrange(gpio_pins[i], 256)) < 0) {
            fprintf(stderr, "Failed to set range for GPIO %d: %s\n", gpio_pins[i], pigpio_error_text(ret));
            goto cleanup;
        }
        if ((ret = gpioSetPWMdutycycle(gpio_pins[i], 128)) < 0) {
            fprintf(stderr, "Failed to set duty cycle for GPIO %d: %s\n", gpio_pins[i], pigpio_error_text(ret));
            goto cleanup;
        }
        printf("GPIO %d: PWM set to 50%%\n", gpio_pins[i]);
    }

cleanup:
    // Clean up GPIO settings
    for (size_t i = 0; i < num_pins; ++i) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Stop pigpio library
    pigpio_stop();

    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

