#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define CAPTURE_SIZE 1920 * 1080 * 3 // Example size for RGB format

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer;

    // Open the video device
    if ((fd = open(DEVICE, O_RDWR)) == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Check if the device supports V4L2
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the desired format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffer
    buffer = malloc(CAPTURE_SIZE);
    if (!buffer) {
        perror("Failed to allocate buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start stream");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture one frame
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the captured image to a file
    FILE *file = fopen("captured_image.rgb", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, 1, CAPTURE_SIZE, file) != CAPTURE_SIZE) {
        perror("Failed to write to file");
        fclose(file);
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(file);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Failed to stop stream");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Free resources
    free(buffer);
    close(fd);

    printf("Image captured successfully and saved as 'captured_image.rgb'\n");

    return EXIT_SUCCESS;
}

