    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            goto cleanup;
        }
    }

    // Configure lines as outputs
    for (int i = 0; i < 4; i++) {
        ret = gpiod_line_request_output(lines[i], "output", 0);
        if (ret < 0) {
            perror("Failed to request output");
            goto cleanup;
        }
    }

    while (running) {
        // Toggle states
        for (int i = 0; i < 4; i++) {
            ret = gpiod_line_set_value(lines[i], !gpiod_line_get_value(lines[i]));
            if (ret < 0) {
