    perror(message);
    cleanup();
    exit(EXIT_FAILURE);
}

int read_temperature(const char *device_path) {
    int fd = open(device_path, O_RDONLY);
    if (fd == -1) {
        handle_error("Failed to open device file");
    }

    char buffer[MAX_TEMP_LENGTH];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
    close(fd);

    if (bytes_read <= 0) {
        handle_error("Failed to read from device file");
    }

    // Find the temperature value in the buffer
    char *temp_str = strstr(buffer, "t=");
    if (!temp_str) {
        handle_error("Temperature not found in device data");
    }

    temp_str += 2; // Move past "t="
    long temp_raw = strtol(temp_str, NULL, 10);
    double temp_celsius = temp_raw / 1000.0;

    return (int)temp_celsius;
}

int main() {
    atexit(cleanup);

    // Enable GPIO pin 4 as an input
    const char *gpio_export_path = "/sys/class/gpio/export";
    int export_fd = open(gpio_export_path, O_WRONLY);
    if (export_fd == -1) {
        handle_error("Failed to open gpio export file");
    }
    write(export_fd, &GPIO_PIN, sizeof(GPIO_PIN));
    close(export_fd);

    // Set GPIO pin 4 as an input
    char gpio_direction_path[64];
    snprintf(gpio_direction_path, sizeof(gpio_direction_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    int direction_fd = open(gpio_direction_path, O_WRONLY);
    if (direction_fd == -1) {
        handle_error("Failed to open gpio direction file");
    }
    write(direction_fd, "in", 2);
    close(direction_fd);

    // Wait for the device to be ready
    sleep(1);

    // Read the temperature three times, once every five seconds
    for (int i = 0; i < 3; ++i) {
        const char *w1_slave_path = "/sys/bus/w1/devices/28-*/w1_slave"; // Adjust path based on your setup
        DIR *dir = opendir("/sys/bus/w1/devices/");
        if (!dir) {
            handle_error("Failed to open w1 devices directory");
        }

        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, "28-", 3) == 0) {
                char full_path[256];
                snprintf(full_path, sizeof(full_path), "/sys/bus/w1/devices/%s/w1_slave", entry->d_name);
                int temp = read_temperature(full_path);
                printf("Temperature: %d°C\n", temp);
