#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_dht22(struct gpiod_chip *chip, int line_num) {
    struct gpiod_line *line;
    unsigned int data[5] = {0};
    int i, j, sum = 0;

    line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(line, "dht22", GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH)) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    // Start condition: pull low for at least 18ms
    gpiod_line_set_value(line, 0);
    usleep(20000);

    // Release line and wait for response
    gpiod_line_set_value(line, 1);
    usleep(30);

    // Read data from DHT22
    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            while (gpiod_line_get_value(line) == 0)
                usleep(1);
            usleep(40);
            if (gpiod_line_get_value(line) == 1) {
                data[i] |= (1 << (7 - j));
                while (gpiod_line_get_value(line) == 1)
                    usleep(1);
            }
        }
    }

    // Check checksum
    sum = data[0] + data[1] + data[2] + data[3];
    if (data[4] != sum) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    printf("Temperature: %d.%d°C, Humidity: %d.%d%%\n",
           data[2], data[3] / 10, data[0], data[1] / 10);

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    for (int cycle = 0; cycle < 3 && running; cycle++) {
        ret = read_dht22(chip, GPIO_LINE);
        if (ret < 0) {
            fprintf(stderr, "Reading failed, retrying...\n");
            sleep(2);
        } else {
            sleep(2);
        }
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

