    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gpios[NUM_PWM_GPIOS] = PWM_GPIOS;
    for (int i = 0; i < NUM_PWM_GPIOS; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", gpios[i]);
