        for (int i = 0; i < NUM_PWM_GPIOS; i++) {
            gpioSetPWMrange(gpios[i], 256);
            gpioSetPWMrange(gpios[i], 128);
            gpioSetPWMrange(gpios[i], 64);
            gpioSetPWMrange(gpios[i], 32);
            gpioSetPWMrange(gpios[i], 16);
