    line_17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line_17) {
        perror("Failed to get GPIO line 17");
        goto error;
    }

    for (int i = 0; i < 3; ++i) {
        int humidity;
        float temperature;

        if (read_dht22(line_4, &humidity, &temperature)) {
            fprintf(stderr, "Failed to read DHT22\n");
            continue;
        }

        printf("Cycle %d: Humidity=%d%% Temperature=%.1f°C\n", i + 1, humidity, temperature);
        sleep(60);
    }

    cleanup(0);

error:
    if (line_4) {
        gpiod_line_release(line_4);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_FAILURE;
}

