    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_GPIO_17, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_18, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_27, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_GPIO_17, 500);
    gpioSetPWMrange(PWM_GPIO_17, 256);
    gpioSetPWMfrequency(PWM_GPIO_18, 500);
    gpioSetPWMrange(PWM_GPIO_18, 256);
    gpioSetPWMfrequency(PWM_GPIO_27, 500);
    gpioSetPWMrange(PWM_GPIO_27, 256);

    signal(SIGINT, signal_handler);

    while (!stop) {
        for (int i = 0; i <= 255; i++) {
            gpioSetPWMdutycycle(PWM_GPIO_17, i);
            gpioSetPWMdutycycle(PWM_GPIO_18, i);
