#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 500000

int spi_fd;

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void die(const char *msg) {
    perror(msg);
    close_spi();
    exit(EXIT_FAILURE);
}

uint16_t read_max31855() {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0)
        die("SPI_IOC_MESSAGE");

    return ((uint16_t)rx[0] << 8) | rx[1];
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0)
        die("Failed to open SPI device");

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0)
        die("Failed to set SPI mode");
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0)
        die("Failed to set bits per word");
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0)
        die("Failed to set max speed HZ");

    uint16_t temp = read_max31855();

    printf("Temperature: %u\n", temp);

    close_spi();
    return EXIT_SUCCESS;
}

