#include <string.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIG_PIN "gpiochip0:line4"
#define ECHO_PIN "gpiochip0:line17"

void cleanup(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request trigger line
    trig = gpiod_chip_get_line(chip, 4);
    if (!trig) {
        perror("Failed to get trigger line");
        goto err_close_chip;
    }

    // Configure trigger line as output
    ret = gpiod_line_request_output(trig, "HC-SR04 Trigger", 0);
    if (ret < 0) {
        perror("Failed to configure trigger line as output");
        goto err_release_trig;
    }

    // Request echo line
    echo = gpiod_chip_get_line(chip, 17);
    if (!echo) {
        perror("Failed to get echo line");
        goto err_release_trig;
    }

    // Configure echo line as input
    ret = gpiod_line_request_input(echo, "HC-SR04 Echo");
    if (ret < 0) {
        perror("Failed to configure echo line as input");
        goto err_release_echo;
    }

    // Send trigger pulse
    ret = gpiod_line_set_value(trig, 1);
    if (ret < 0) {
        perror("Failed to set trigger line high");
        goto err_release_echo;
    }
    usleep(10); // 10 microseconds pulse width
    ret = gpiod_line_set_value(trig, 0);
    if (ret < 0) {
        perror("Failed to set trigger line low");
        goto err_release_echo;
    }

    // Wait for echo to go high
    ret = gpiod_line_event_wait(echo, 500000); // 500 milliseconds timeout
    if (ret < 0) {
        perror("Failed to wait for echo line event");
        goto err_release_echo;
    }

    // Read echo line state
    unsigned int echo_state;
    ret = gpiod_line_get_value(echo, &echo_state);
    if (ret < 0) {
        perror("Failed to read echo line state");
        goto err_release_echo;
    }

    printf("Echo State: %u\n", echo_state);

err_release_echo:
    gpiod_line_release(echo);
err_release_trig:
    gpiod_line_release(trig);
err_close_chip:
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

