#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDRESS 0x76
#define BMP280_MEASUREMENT_REG 0xFA

int main() {
    int fd;
    char filename[20];
    unsigned char buffer[3];

    // Open the I2C bus
    snprintf(filename, 19, "/dev/i2c-1");
    if ((fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; ++i) {
        // Read 3 bytes from the BMP280 sensor
        if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from the sensor");
            close(fd);
            return EXIT_FAILURE;
        }

        // Convert the raw data to temperature (simplified example)
        int temp_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        float temperature = (temp_raw / 100.0);

        printf("Temperature: %.2f°C\n", temperature);
    }

    // Release the I2C bus
    close(fd);
    return EXIT_SUCCESS;
}

