#include <signal.h>
#include <libgpiod.h>

#define CONSUMER "gpio_output_control"
#define CHIP_NAME "0" // Typically "/dev/gpiochip0"

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
int line_nums[] = {17, 22, 23, 24};

void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup done.\n");
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_nums[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            goto error;
        }

        int ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            goto error;
        }

        printf("Set GPIO %d to low\n", line_nums[i]);
    }

    // Set all lines high
    for (int i = 0; i < 4; i++) {
        int ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            goto error;
        }

        printf("Set GPIO %d to high\n", line_nums[i]);
    }

    // Wait for a moment before exiting
    sleep(1);

    // Clean up and exit
    cleanup(EXIT_SUCCESS);

error:
    cleanup(EXIT_FAILURE);
    return EXIT_FAILURE;
}

