int main() {
    int i2c_fd;
    int temperature;

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    // Read temperature three times with a 5-second interval
    for (int i = 0; i < 3; ++i) {
        temperature = bme280_read_temperature(i2c_fd);
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature\n");
            i2c_close(i2c_fd);
            return EXIT_FAILURE;
        }
        printf("Temperature: %.2f°C\n", temperature / 100.0);
        sleep(5);
    }

    // Close I2C device
    i2c_close(i2c_fd);
    return EXIT_SUCCESS;
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

int bme280_read_temperature(int fd) {
    unsigned char data[3];
    if (read(fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Calculate temperature in millidegrees Celsius
    int32_t adc_T = ((data[0] << 16) | (data[1] << 8) | data[2]);
    int32_t var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * calib.dig_T2) >> 11);
    int32_t var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * calib.dig_T3) >> 14;
    int32_t t_fine = var1 + var2;
    float temperature = (t_fine * 5 + 128) >> 8;

    return (int)(temperature * 100);
}

