#include <termios.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B9600
#define TIMEOUT_SEC 0
#define TIMEOUT_USEC 100000

int open_serial(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open serial port");
        return -1;
    }

    struct termios options;
    tcgetattr(fd, &options);

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    tcsetattr(fd, TCSANOW, &options);

    return fd;
}

void close_serial(int fd) {
    close(fd);
}

int read_from_serial(int fd, char *buffer, size_t buffer_size) {
    fd_set set;
    FD_ZERO(&set);
    FD_SET(fd, &set);

    struct timeval timeout;
    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int ret = select(fd + 1, &set, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("Select failed");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout occurred\n");
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Read failed");
        return -1;
    }

    buffer[bytes_read] = '\0';
    return bytes_read;
}

int main() {
    int fd = open_serial(UART_DEVICE);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    while (1) {
        int bytes_read = read_from_serial(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("%.*s", bytes_read, buffer);
        } else if (bytes_read == -1) {
            close_serial(fd);
            return EXIT_FAILURE;
        }

        usleep(100000); // 0.1 seconds
    }

    close_serial(fd);
    return EXIT_SUCCESS;
}

