#define TRIG_PIN "gpiochip0:line17"
#define ECHO_PIN "gpiochip0:line18"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    int distance = -1;

    // Set trig line to low for at least 2 microseconds
    gpiod_line_set_value(trig, 0);
    usleep(2);

    // Set trig line to high for 10 microseconds
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    // Wait for echo line to go high
    while (!gpiod_line_get_value(echo)) {
        if (!running) return -1;
        usleep(1);
    }

    // Measure time until echo line goes low
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo)) {
        if (!running) return -1;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    long duration_ns = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    distance = (duration_ns / 2) / 29.1; // Speed of sound in air at room temperature

    return distance;
}

