    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request trig line
    trig_line = gpiod_chip_get_line(chip, 4);
    if (!trig_line) {
        perror("Failed to get trig line");
        goto cleanup_chip;
    }
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trig line as output");
        goto cleanup_trig_line;
    }

    // Request echo line
    echo_line = gpiod_chip_get_line(chip, 17);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto cleanup_trig_line;
    }
    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        goto cleanup_echo_line;
    }

    while (running) {
        // Trigger pulse
        ret = gpiod_line_set_value(trig_line, 1);
        if (ret < 0) {
            perror("Failed to set trig line high");
            break;
        }
        usleep(10); // 10 microseconds
        ret = gpiod_line_set_value(trig_line, 0);
        if (ret < 0) {
            perror("Failed to set trig line low");
            break;
        }

        // Wait for echo pulse
        unsigned int start_time = 0, end_time = 0;
        ret = gpiod_line_event_wait(echo_line, 100000); // 100 milliseconds
        if (ret < 0) {
            perror("Failed to wait for echo event");
            break;
        }
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo event");
            break;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            start_time = event.timestamp.tv_nsec / 1000; // Convert to microseconds
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            end_time = event.timestamp.tv_nsec / 1000; // Convert to microseconds
        }

        if (start_time && end_time) {
            unsigned long duration = end_time - start_time;
            double distance = (duration * 0.343) / 2.0; // Speed of sound in air at room temperature
            printf("Distance: %.2f cm\n", distance);
        }

        usleep(100000); // 0.1 seconds
    }

cleanup_echo_line:
    gpiod_line_release(echo_line);
cleanup_trig_line:
    gpiod_line_release(trig_line);
cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

