#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B9600

void set_interface_attribs(int fd, int speed) {
    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error from tcgetattr");
        exit(EXIT_FAILURE);
    }

    cfsetospeed(&tty, (speed_t)speed);
    cfsetispeed(&tty, (speed_t)speed);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;         /* 8-bit characters */
    tty.c_cflag &= ~PARENB;     /* no parity bit */
    tty.c_cflag &= ~CSTOPB;     /* only need 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;    /* no hardware flowcontrol */

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); /* raw input */

    tty.c_oflag &= ~OPOST;      /* raw output */

    tty.c_cc[VTIME] = 10;    /* inter-character timeout (deciseconds) */
    tty.c_cc[VMIN] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error from tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int fd;
    char read_buf[256];
    ssize_t num_bytes_read;

    // Open the serial port
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Unable to open UART device");
        return EXIT_FAILURE;
    }

    // Set up the serial port attributes
    set_interface_attribs(fd, BAUD_RATE);

    // Main loop
    while (!feof(stdin)) {
        num_bytes_read = read(fd, read_buf, sizeof(read_buf) - 1);
        if (num_bytes_read > 0) {
            read_buf[num_bytes_read] = '\0';
            printf("%s", read_buf);
        } else if (num_bytes_read == -1 && errno != EAGAIN) {
            perror("Error reading from UART");
            close(fd);
            return EXIT_FAILURE;
        }
        usleep(100 * 1000); // Sleep for 0.1 seconds
    }

    // Clean up
    close(fd);
    return EXIT_SUCCESS;
}

