#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIG_PIN "gpiochip0:line18"
#define ECHO_PIN "gpiochip0:line23"

void cleanup(struct gpiod_chip *chip, struct gpiod_line *trig_line, struct gpiod_line *echo_line) {
    if (trig_line) {
        gpiod_line_release(trig_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request trig line
    trig_line = gpiod_chip_get_line(chip, 18);
    if (!trig_line) {
        perror("Failed to get trig line");
        goto error;
    }

    // Configure trig line as output
    if (gpiod_line_request_output(trig_line, "HC-SR04 Trig", 0)) {
        perror("Failed to request trig line as output");
        goto error;
    }

    // Request echo line
    echo_line = gpiod_chip_get_line(chip, 23);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto error;
    }

    // Configure echo line as input
    if (gpiod_line_request_input(echo_line, "HC-SR04 Echo")) {
        perror("Failed to request echo line as input");
        goto error;
    }

    // Send trigger pulse
    if (gpiod_line_set_value(trig_line, 1)) {
        perror("Failed to set trig line high");
        goto error;
    }
    usleep(10); // 10 microseconds pulse
    if (gpiod_line_set_value(trig_line, 0)) {
        perror("Failed to set trig line low");
        goto error;
    }

    // Wait for echo pulse
    int timeout_ms = 5000; // 5 seconds
    while (timeout_ms > 0) {
        int value = gpiod_line_get_value(echo_line);
        if (value == 1) {
            break;
        }
        usleep(1000); // 1 millisecond
        timeout_ms -= 1;
    }

    if (timeout_ms <= 0) {
        fprintf(stderr, "No echo received within timeout\n");
        goto error;
    }

    // Measure duration of echo pulse
    uint64_t start_time = gpiod_line_event_wait(echo_line, 0);
    uint64_t end_time = gpiod_line_event_wait(echo_line, 0);

    if (start_time == -1 || end_time == -1) {
        perror("Failed to wait for echo event");
        goto error;
    }

    uint64_t duration_ns = end_time - start_time;
    double distance_cm = (duration_ns / 29.1) / 2.0; // Speed of sound in air at room temperature

    printf("Distance: %.2f cm\n", distance_cm);

    cleanup(chip, trig_line, echo_line);
    return EXIT_SUCCESS;

error:
    cleanup(chip, trig_line, echo_line);
    return EXIT_FAILURE;
}

