    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_request_output(lines[i], "output", 0);
        if (ret < 0) {
            perror("Failed to request output");
            goto cleanup;
        }
    }

    while (running) {
        // Toggle states
        for (int i = 0; i < 3; i++) {
            ret = gpiod_line_set_value(lines[i], !gpiod_line_get_value(lines[i]));
