void read_mpu6050_data(uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    uint8_t buffer[6];

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        // Read accelerometer and gyroscope data
        read_mpu6050_data(0x3B, buffer, sizeof(buffer));

        // Convert raw data to signed integers
        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

