#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    bool value = false;

    // Register signal handler for clean exit
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        goto close_chip;
    }

    // Configure line as output
    ret = gpiod_line_request_output(line, "output_example", value);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        goto release_line;
    }

    while (1) {
        // Toggle the GPIO line
        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            break;
        }

        // Print the current state
        printf("GPIO %d: %s\n", GPIO_LINE, value ? "HIGH" : "LOW");

        // Sleep for 0.6 seconds
        sleep(3 / 5);
    }

release_line:
    gpiod_line_release(line);
close_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}
